"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9999],{46586:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Initialises all audio subsystems and must be called exactly once, from\\nthe client bootstrap (`SoundController.client.luau`).\\n\\nCalling `Init` more than once is a no-op.  On first call it:\\n- Ensures SoundGroups and the positional SFX pool exist in the DataModel.\\n- Connects the server-replication listener for positional sounds.\\n- Warms per-asset positional pools so the first `PlaySFXAt` is instant.\\n- Auto-starts any ambience beds listed in `SoundConfig.Ambience.Autostart`.","params":[],"returns":[],"function_type":"static","source":{"line":47,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlaySFX","desc":"Plays a non-positional (2D) one-shot sound effect by its config name.\\n\\nThe sound is looked up in `SoundConfig.Sfx`, played through the\\nappropriate `SoundGroup`, then destroyed automatically when it ends.\\nSubject to per-asset debounce if configured.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx` (e.g. `\\"refuel_success\\"`).","lua_type":"string"},{"name":"opts","desc":"Optional overrides for volume, pitch, debounce, and replication.","lua_type":"PlayOptions?"}],"returns":[],"function_type":"static","source":{"line":88,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlaySFXAt","desc":"Plays a positional (3D) one-shot sound effect anchored at `position`.\\n\\nUses the pooled `Sound` / `Part` system for instant playback.  If\\n`opts.Replicate` (or the config `Replicate` flag) is `true`, a packet\\nis fired to replicate the sound on all other clients.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx`.","lua_type":"string"},{"name":"position","desc":"World-space origin of the sound.","lua_type":"Vector3"},{"name":"opts","desc":"Optional overrides for volume, pitch, debounce, and replication.","lua_type":"PlayOptions?"}],"returns":[],"function_type":"static","source":{"line":103,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlayLooped","desc":"Starts a looping sound and returns a `LoopHandle` for runtime control.\\n\\nThe handle exposes `:FadeTo(volume, duration?)`, `:Stop(fadeDuration?)`,\\nand `:Destroy()`.  Returns `nil` if the name is unknown or has no asset\\nid.  Pass `opts.FadeIn` to ramp the volume up from zero on start.","params":[{"name":"name","desc":"Key in `SoundConfig.Sfx`.","lua_type":"string"},{"name":"opts","desc":"Optional overrides; `FadeIn` fades from 0 to target volume.","lua_type":"PlayOptions?"}],"returns":[{"desc":"Control handle, or `nil` if the asset is not configured.","lua_type":"LoopHandle?"}],"function_type":"static","source":{"line":118,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"PlayMusic","desc":"Starts the music system, optionally targeting a named playlist.\\n\\nIf `playlistName` is omitted the default playlist defined in\\n`SoundConfig` is used.  Calling while music is already playing\\nperforms a crossfade into the new playlist.","params":[{"name":"playlistName","desc":"Name of a playlist in `SoundConfig`; omit for the default.","lua_type":"string?"}],"returns":[],"function_type":"static","source":{"line":134,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SkipMusic","desc":"Skips the currently playing music track and advances to the next one\\nin the active playlist.","params":[],"returns":[],"function_type":"static","source":{"line":143,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"StopMusic","desc":"Stops the currently playing music track.","params":[{"name":"fade","desc":"Fade-out duration in seconds; stops immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":152,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SetAmbience","desc":"Replaces the active ambience bed set with exactly the supplied list.\\n\\nBeds currently playing that are absent from `names` are faded out;\\nbeds in `names` that are not yet playing are faded in.","params":[{"name":"names","desc":"Array of ambience-bed config names to make active.","lua_type":"{string}"},{"name":"fade","desc":"Crossfade duration in seconds; snaps instantly when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":168,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"AddAmbience","desc":"Fades in a single ambience bed without affecting others that are\\nalready playing.","params":[{"name":"name","desc":"Ambience-bed config name to add.","lua_type":"string"},{"name":"fade","desc":"Fade-in duration in seconds; starts at full volume when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":179,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"RemoveAmbience","desc":"Fades out and stops a single ambience bed without affecting others.","params":[{"name":"name","desc":"Ambience-bed config name to remove.","lua_type":"string"},{"name":"fade","desc":"Fade-out duration in seconds; stops immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":189,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"StopAmbience","desc":"Fades out and stops all currently playing ambience beds.","params":[{"name":"fade","desc":"Fade-out duration in seconds; stops all immediately when omitted.","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":198,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"SetVolume","desc":"Sets the master volume of a named `SoundGroup` bus.\\n\\nValid group names match the keys defined in `SoundConfig.GroupVolumes`:\\n`\\"Master\\"`, `\\"SFX\\"`, `\\"BGM\\"`, `\\"Ambience\\"`.","params":[{"name":"group","desc":"`SoundGroup` bus name.","lua_type":"string"},{"name":"volume","desc":"Target volume in the range `[0, 1]`.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":214,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}},{"name":"GetVolume","desc":"Returns the current volume of a named `SoundGroup` bus.","params":[{"name":"group","desc":"`SoundGroup` bus name.","lua_type":"string"}],"returns":[{"desc":"Current volume in the range `[0, 1]`.","lua_type":"number"}],"function_type":"static","source":{"line":226,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}}],"properties":[],"types":[],"name":"SoundManager","desc":"Single entry point for all client audio (SFX, BGM, ambience).\\nCall `Init` once from `SoundController.client.luau`; all other client\\nscripts and tools call the `Play*`, `Music`, `Ambience`, and volume\\nmethods.  Never create ad-hoc `Sound` instances \u2014 let SoundManager\\nmanage pooling, grouping, and replication.  Asset ids, volumes, pitch\\nranges, and playlist definitions live in `Configs/SoundConfig`.","realm":["Client"],"source":{"line":17,"path":"src/ReplicatedStorage/SharedModules/SoundManager/init.luau"}}')}}]);